"""Compare version-specific native Qfile preparation with complete saved original BESDs, including retained inconsistent-P controls."""
import argparse,json,os,subprocess
from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from validate_mashr_native import JAVA21


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--build',required=True,type=Path);p.add_argument('--out',required=True,type=Path);a=p.parse_args();out=a.out.resolve();base=ROOT/'build/literature-review/smr-runtime';assert out.is_relative_to(base) and not out.exists();out.mkdir(parents=True);build=json.loads((a.build/'COMPLETED.json').read_bytes());jar=ROOT/build['artifact']['path'];assert pin(jar)=={k:build['artifact'][k] for k in ['bytes','sha256']};cases=[base/'workflow-core-probe-3'/(version+'-'+storage) for version in ['1.3.1','1.4.3'] for storage in ['sparse','dense']]+[base/'workflow-edge-probe-1/1.3.1-overlap',base/'workflow-edge-probe-1/1.3.1-alignment-missing-frequency'];source_pins={n:pin(ROOT/n) for n in [*build['source_pins'],Path(__file__).resolve().relative_to(ROOT).as_posix()]};assert all(source_pins[n]==v for n,v in build['source_pins'].items());runner=out/'SmrPreparationProbe.java';runner.write_text('''package org.jlinalg.cli;import java.nio.file.*;import java.util.*;import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
public final class SmrPreparationProbe{public static void main(String[] args)throws Exception{Path root=Path.of(args[0]),out=Path.of(args[1]);var m=object(NextflowParameters.parse(Files.readString(root.resolve("request.json")),1048576,100000));var q=object(m.get("qtl"));q.put("preparation_policy","source-version-with-ledger");m.put("qtl",q);m.put("analyses",java.util.List.of(list(m.get("analyses")).get(0)));var r=SmrWorkflowRequest.parse(m,root);var b=new SmrWorkflowInputs.Budget(r.nativeOperations());var supplied=SmrWorkflowInputs.qfile(root.resolve("analysis/inputs/qtl.qfile"),out.resolve("quantization.tsv"),r,b);var original=SmrWorkflowBesd.read(root.resolve("analysis/worker/prepare/original"),r,b);SmrWorkflowInputs.preparation(supplied,original,out.resolve("complete-comparison.tsv"),b);System.out.println("PASS complete original Qfile population/axes/binary32 preparation "+r.version());}}
''',encoding='utf8',newline='\n');classes=out/'classes';classes.mkdir();command=[str(JAVA21/'javac.exe'),'--release','17','-Xlint:all','-Werror','-encoding','UTF-8','-cp',str(jar),'-d',str(classes),str(runner)];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(out/'compile.stdout').write_bytes(r.stdout);(out/'compile.stderr').write_bytes(r.stderr);assert r.returncode==0,r.stderr.decode(errors='replace');reports=[]
    for i,case in enumerate(cases):
        home=out/str(i);home.mkdir();command=[str(JAVA21/'java.exe'),'-Xmx2g','-cp',os.pathsep.join(map(str,[classes,jar])),'org.jlinalg.cli.SmrPreparationProbe',str(case),str(home)];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(home/'stdout').write_bytes(r.stdout);(home/'stderr').write_bytes(r.stderr);save(home/'process.json',dict(command=command,exit_code=r.returncode));reports.append(dict(control=case.relative_to(ROOT).as_posix(),exit_code=r.returncode,original_inputs={f.relative_to(case).as_posix():pin(f) for f in [case/'request.json',case/'analysis/inputs/qtl.qfile',*[case/('analysis/worker/prepare/original'+suffix) for suffix in ['.besd','.epi','.esi']]]}));print(case.name,'exit',r.returncode,flush=True)
    assert all(pin(ROOT/n)==v for n,v in source_pins.items());passed=all(r['exit_code']==0 for r in reports);save(out/'COMPLETED.json',dict(status='passed-native-Qfile-preparation-against-complete-original-BESDs' if passed else 'FAIL2_NATIVE_QFILE_PREPARATION_MISMATCH',artifact=build['artifact'],source_pins=source_pins,controls=reports,adapter_admitted=False,implementation_credit=False,whole_goal_complete=False));return 0 if passed else 2


if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable source/original-preparation checks')
    raise SystemExit(main())
